def add_contact(phonebook, name, phone_number):
    """Add a contact to the phonebook dictionary."""
    if name in phonebook:
        print(f"Contact already exists: {name} - {phone_number}")
    else:
        phonebook[name] = phone_number
        print(f"Contact added: {name} - {phone_number}")

def remove_contact(phonebook, name):
    """Remove a contact from the phonebook dictionary."""
    if name in phonebook:
        del phonebook[name]
        print(f"Contact removed: {name}")
    else:
        print(f"Contact not found: {name}")

def search_contact(phonebook, name):
    """Search for a contact in the phonebook dictionary."""
    if name in phonebook:
        print(f"Contact found: {name} - {phonebook[name]}")
    else:
        print(f"Contact not found: {name}")

# Initialize the phonebook dictionary
phonebook = {}

# User input loop
while True:
    user_input = input("Enter a command (add, remove, search, or quit): ").lower()

    if user_input == "add":
        name = input("Enter name: ")
        phone_number = input("Enter phone number: ")
        add_contact(phonebook, name, phone_number)

    elif user_input == "remove":
        name = input("Enter name: ")
        remove_contact(phonebook, name)

    elif user_input == "search":
        name = input("Enter name: ")
        search_contact(phonebook, name)

    elif user_input == "quit":
        break

    else:
        print("Invalid command. Please try again.")

print("Phonebook updated. Goodbye!")
